const POINTS: [number, number][] = [
  [1, 100], [2, 50], [3, 30], [4, 20], [5, 16], [6, 15], [7, 14], [8, 13],
  [9, 12], [10, 11], [11, 10], [12, 9], [13, 8], [14, 7], [15, 6], [16, 5],
